// Generated by vite.config.js at build time.
const VERSION = 'kjvu9a'
const SHELL = 'atlas-shell-' + VERSION
const DATA = 'atlas-data-v2' // models change rarely; bump when any file in public/models changes
const BASE = self.registration.scope // ends with /, works at the site root or under /repo-name/
const PRECACHE = ["./","manifest.webmanifest","icon.svg","icon-192.png","icon-512.png","assets/index-CKXlojGB.css","assets/index-DBvDo-UC.js","assets/Effects-DbU4S-4e.js"].map((p) => new URL(p, BASE).href)

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(SHELL).then((c) => c.addAll(PRECACHE)).then(() => self.skipWaiting()))
})

self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys()
    .then((keys) => Promise.all(keys.filter((k) => (k.startsWith('atlas-shell-') && k !== SHELL) || (k.startsWith('atlas-data-') && k !== DATA)).map((k) => caches.delete(k))))
    .then(() => self.clients.claim()))
})

const cacheFirst = async (req, name) => {
  const hit = await caches.match(req)
  if (hit) return hit
  const res = await fetch(req)
  if (res.ok || res.type === 'opaque') (await caches.open(name)).put(req, res.clone())
  return res
}

self.addEventListener('fetch', (e) => {
  const req = e.request
  if (req.method !== 'GET') return
  const url = new URL(req.url)
  // Pages: network first so a deploy shows up at once; offline, the cached copy (or the app shell).
  if (req.mode === 'navigate') {
    e.respondWith(fetch(req).then((res) => {
      const copy = res.clone()
      caches.open(SHELL).then((c) => c.put(req, copy))
      return res
    }).catch(async () => (await caches.match(req)) || caches.match(BASE)))
    return
  }
  if (url.origin === location.origin && (url.pathname.startsWith(new URL('models/', BASE).pathname) || url.pathname.startsWith(new URL('organs/', BASE).pathname))) e.respondWith(cacheFirst(req, DATA))
  else if (url.origin === location.origin || /fonts\.(googleapis|gstatic)\.com$/.test(url.hostname)) e.respondWith(cacheFirst(req, SHELL))
})
